import{_ as t,o,c as r,a6 as a}from"./chunks/framework.CCKCzdWs.js";const w=JSON.parse('{"title":"Remote development","description":"Use the Piwi editor extensions in a remote VS Code window (Remote SSH, WSL, Dev Containers, Codespaces) or on a JetBrains Gateway backend, and reach their runs from Piwi Picker through a forwarded port.","frontmatter":{"title":"Remote development","description":"Use the Piwi editor extensions in a remote VS Code window (Remote SSH, WSL, Dev Containers, Codespaces) or on a JetBrains Gateway backend, and reach their runs from Piwi Picker through a forwarded port.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/remote-development.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/remote-development.html"}],["meta",{"property":"og:title","content":"Remote development | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Use the Piwi editor extensions in a remote VS Code window (Remote SSH, WSL, Dev Containers, Codespaces) or on a JetBrains Gateway backend, and reach their runs from Piwi Picker through a forwarded port."}]]},"headers":[],"relativePath":"guide/remote-development.md","filePath":"guide/remote-development.md","lastUpdated":1793225917000}'),i={name:"guide/remote-development.md"};function n(s,e,d,h,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="remote-development" tabindex="-1">Remote development <a class="header-anchor" href="#remote-development" aria-label="Permalink to &quot;Remote development&quot;">​</a></h1><p>In remote development the editor&#39;s window is on your computer, while the code, the <a href="/features/editors.html">editor service</a> and the test runs are on another machine: a server over SSH, WSL, a dev container or a codespace. What the editor shows from the service works there as it does on your computer: failures, runs, <a href="/features/editor-run-control.html">pausing and stepping</a>, a headless stop&#39;s image and Pick on it, <a href="/features/editor-stop-code.html">code from a pause</a>. <a href="/features/extension.html">Piwi Picker</a> is the part that needs a word: it runs in the browser on your computer and reaches the editor through a pairing address on the loopback interface, which in remote development is the local end of a forwarded port.</p><h2 id="vs-code" tabindex="-1">VS Code <a class="header-anchor" href="#vs-code" aria-label="Permalink to &quot;VS Code&quot;">​</a></h2><p>In a remote window (Remote SSH, WSL, Dev Containers, or a codespace opened in VS Code desktop):</p><ol><li>Run <strong>Piwi: Pair with Piwi Picker</strong> in that window. VS Code forwards the window&#39;s Send to editor port to your computer, on the same number when it is free there, and copies the local end on <code>127.0.0.1</code>, whatever name VS Code gives it: <code>http://127.0.0.1:&lt;port&gt;/piwi/send#&lt;token&gt;</code>.</li><li>Paste it in Piwi Picker&#39;s settings under <strong>Send to editor</strong> and click <strong>Pair</strong>.</li></ol><p>Piwi Picker then sends locators and recordings to the remote window, and its <a href="/features/runs-window.html">Runs window</a> lists the runs that window starts, and shows a headless test&#39;s page live: when Piwi Picker asks for them, VS Code forwards the port of the window&#39;s run hub too, and the hub accepts a connection on that local port once the window has named it, which Piwi Picker reaches on <code>127.0.0.1</code> too. Both forwarded ports show in the <strong>Ports</strong> view. The pairing&#39;s token, the proof that the editor holds it, and the browser extension&#39;s origin are checked as on your own computer.</p><p>One pairing reaches the runs of one window when it is remote, and of every local window when it is local: pair from the window whose runs you follow. After the window reloads, VS Code forwards the pairing&#39;s port again; when it lands on another local port, pair again.</p><h3 id="codespaces-in-the-browser" tabindex="-1">Codespaces in the browser <a class="header-anchor" href="#codespaces-in-the-browser" aria-label="Permalink to &quot;Codespaces in the browser&quot;">​</a></h3><p>A codespace opened in a browser tab forwards ports to an <code>https://…app.github.dev</code> address behind GitHub&#39;s sign-in, not to your computer&#39;s loopback interface. Piwi Picker pairs with a loopback address only, so neither Send to editor nor the Runs window reaches a codespace in the browser: open it in VS Code desktop instead.</p><h2 id="jetbrains-gateway" tabindex="-1">JetBrains Gateway <a class="header-anchor" href="#jetbrains-gateway" aria-label="Permalink to &quot;JetBrains Gateway&quot;">​</a></h2><p>A JetBrains Gateway backend runs the IDE, its built-in server and the editor service on the remote machine. The platform offers plugins no supported way to forward a port to your computer, so you forward the ports yourself:</p><ol><li>Run <strong>Tools → Piwi → Pair with Piwi Picker</strong> in the remote IDE. Besides copying the pairing address, its notification names the IDE&#39;s port (63342 by default) and the ports of the open projects&#39; runs.</li><li>In the JetBrains Client, forward each of them under <strong>Ports</strong>, with the local port the same as the host port.</li><li>Paste the pairing address in Piwi Picker&#39;s settings under <strong>Send to editor</strong>.</li></ol><p>The numbers must match: Piwi Picker checks the IDE&#39;s proof for the port it asked on, and a run&#39;s hub accepts its own port alone. A project&#39;s run port changes when its editor service starts again (the IDE restarted, the project was reopened): pair again, and forward the port the notification names.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/editor-run-control.html">Pause and step from the editor</a>: the runs Piwi Picker follows.</li><li><a href="/features/extension.html">Piwi Picker</a>: the Runs window and Send to editor.</li><li><a href="/features/editor-recording.html#send-from-piwi-picker">Record tests from the editor</a>: pairing Piwi Picker with the editor.</li><li><a href="/features/editor-connection.html">Editor connection</a>: the instance and the desktop app a remote window reads.</li></ul>',15)])])}const m=t(i,[["render",n]]);export{w as __pageData,m as default};
